import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load GLB mesh from provided URL
  const meshUrl = config.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb';
  const gltf = ctx.glbLoader(meshUrl);
  const mesh = gltf.scene;
  group.add(mesh);

  // Apply scene placement from config
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition[0],
      config.scenePosition[1],
      config.scenePosition[2]
    );
  }
  if (config.rotation) {
    group.rotation.set(
      config.rotation[0],
      config.rotation[1],
      config.rotation[2]
    );
  }
  if (config.scale) {
    group.scale.set(
      config.scale[0],
      config.scale[1],
      config.scale[2]
    );
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (primitive.name && ctx.primitives?.[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Setup interaction state
  const hoverTimeline = gsap.timeline({ paused: true });
  let anchorY = 0;

  // Event handlers
  const handlers = {};

  handlers.onHoverEnter = () => {
    anchorY = group.position.y;
    hoverTimeline.clear();
    hoverTimeline.to(group.position, {
      y: anchorY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.onHoverLeave = () => {
    hoverTimeline.clear();
    hoverTimeline.to(group.position, {
      y: anchorY,
      duration: 0.5,
      ease: 'power2.out'
    });
  };

  handlers.onClick = () => {
    group.dispatchEvent({ type: 'hub-collection.select' });
  };

  group.userData.handlers = handlers;
  group.userData.dataBindings = config.dataBindings || [];

  // Cleanup function
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.rotation);

    mesh.traverse(node => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach(mat => mat.dispose?.());
        } else {
          node.material.dispose?.();
        }
      }
    });
  };

  return group;
}
